"use client";

import { useEffect, useRef, useState } from "react";
import JsBarcode from "jsbarcode";
import type { BarcodeFormat } from "@easyprint/shared/template/barcode";

export type BarcodeSymbolProps = {
  value: string;
  format: BarcodeFormat;
  showHumanReadable?: boolean;
  physical?: boolean;
};

const JS_BARCODE_FORMAT: Record<BarcodeFormat, string> = {
  CODE128: "CODE128",
  EAN13: "EAN13",
  EAN8: "EAN8"
};

export function BarcodeSymbolRenderer({
  value,
  format,
  showHumanReadable = true,
  physical = false
}: BarcodeSymbolProps) {
  const svgRef = useRef<SVGSVGElement | null>(null);
  const [renderError, setRenderError] = useState<string | null>(null);

  useEffect(() => {
    if (!svgRef.current) {
      return;
    }

    setRenderError(null);

    try {
      JsBarcode(svgRef.current, value, {
        format: JS_BARCODE_FORMAT[format],
        displayValue: showHumanReadable,
        text: value,
        lineColor: "#000000",
        background: "#ffffff",
        margin: physical ? 6 : 10,
        width: physical ? 1.4 : 2,
        height: physical ? 38 : 48,
        fontSize: physical ? 12 : 14,
        fontOptions: "bold",
        textMargin: 2
      });
    } catch {
      setRenderError("Codigo invalido para o formato selecionado.");
    }
  }, [format, physical, showHumanReadable, value]);

  if (renderError) {
    return (
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "grid",
          placeItems: "center",
          padding: 4,
          border: "1px solid #b91c1c",
          background: "#fff5f5",
          color: "#991b1b",
          fontSize: 10,
          fontWeight: 700,
          textAlign: "center"
        }}
      >
        {renderError}
      </div>
    );
  }

  return (
    <svg
      ref={svgRef}
      role="img"
      aria-label={`Codigo de barras ${value}`}
      style={{
        width: "100%",
        height: "100%",
        display: "block",
        background: "#ffffff"
      }}
    />
  );
}
